Function fabricada <- CrearMultiplicador(factor As Integer)
  Define fabricada As Function(Integer) As Integer <- Function(x As Integer) As Integer
    Return x * factor;
  EndFunction;
EndFunction

Algorithm Multiplicar
  Define factor, numero As Integer;
  Read factor;
  Define multiplicar As Function(Integer) As Integer <- CrearMultiplicador(factor);
  Read numero;
  While numero <> 0 Do
    Write multiplicar(numero);
    Read numero;
  EndWhile
EndAlgorithm
